        # -- end G1c multi-clause merge ---------------------------------------
        if index + 1 < len(clauses):
            merged = _parse_delayed_pay_or_lose_clauses(clauses, index, for_spell=for_spell)
            if merged is not None:
                consumed, effect = merged
